/** Extension of the base configuration for use in React projects. */
module.exports = {
  parserOptions: {
    ecmaFeatures: {
      jsx: true
    }
  },
  extends: ['plugin:react/recommended', 'plugin:jsx-a11y/recommended'],
  plugins: ['jsx-a11y', 'react', 'react-hooks', 'use-effect-no-deps'],
