import { describe, test, expect, vi, beforeEach, afterEach } from 'vitest';
import { renderHook, act } from '@testing-library/react';
import {
  getSessionJSONItem,
  setSessionJSONItem,
  clearSessionJSONItem,
} from '@salesforce/retail-react-app/app/utils/utils';
import { usePendingWishlistItem } from './usePendingWishlistItem';

// Mocked at the same module boundary useWishlistAuthDrawer.test.tsx already mocks
// (@salesforce/retail-react-app/app/utils/utils), for the same reason: a controllable vi.fn()
// per function rather than exercising real window.sessionStorage.
vi.mock('@salesforce/retail-react-app/app/utils/utils', () => ({
  getSessionJSONItem: vi.fn(() => undefined),
  setSessionJSONItem: vi.fn(),
  clearSessionJSONItem: vi.fn(),
}));

const mockGetSessionJSONItem = vi.mocked(getSessionJSONItem);
const mockSetSessionJSONItem = vi.mocked(setSessionJSONItem);
const mockClearSessionJSONItem = vi.mocked(clearSessionJSONItem);

const PRODUCT_ID = 'product-abc';
const OTHER_PRODUCT_ID = 'product-xyz';
const TEN_MINUTES_MS = 10 * 60 * 1000; // well past the 5-minute bound this hook enforces

describe('usePendingWishlistItem', () => {
  beforeEach(() => {
    vi.clearAllMocks();
    mockGetSessionJSONItem.mockReturnValue(undefined);
  });

  test('a guest is never resumed — onResume is never called while isGuest stays true', () => {
    const onResume = vi.fn();
    const { result, rerender } = renderHook(
      ({ isGuest }) => usePendingWishlistItem({ productId: PRODUCT_ID, isGuest, onResume }),
      {
        initialProps: { isGuest: true },
      },
    );

    act(() => result.current.beginPendingMove());
    rerender({ isGuest: true });

    expect(onResume).not.toHaveBeenCalled();
  });

  test('beginPendingMove persists the intent to session storage, keyed by productId', () => {
    const onResume = vi.fn();
    const { result } = renderHook(() => usePendingWishlistItem({ productId: PRODUCT_ID, isGuest: true, onResume }));

    act(() => result.current.beginPendingMove());

    expect(mockSetSessionJSONItem).toHaveBeenCalledTimes(1);
    const [key, value] = mockSetSessionJSONItem.mock.calls[0];
    expect(key).toBe(`zimmPendingWishlistCartItem:${PRODUCT_ID}`);
    expect(value).toMatchObject({ productId: PRODUCT_ID });
  });

  describe('resume from React state (email-code / create-account auth — the same instance stays mounted)', () => {
    test('a fresh pending item resumes once isGuest flips to false, and both stores are cleared', () => {
      const onResume = vi.fn();
      const { result, rerender } = renderHook(
        ({ isGuest }) => usePendingWishlistItem({ productId: PRODUCT_ID, isGuest, onResume }),
        {
          initialProps: { isGuest: true },
        },
      );

      act(() => result.current.beginPendingMove());
      expect(onResume).not.toHaveBeenCalled();

      rerender({ isGuest: false });

      expect(onResume).toHaveBeenCalledTimes(1);
      expect(mockClearSessionJSONItem).toHaveBeenCalledWith(`zimmPendingWishlistCartItem:${PRODUCT_ID}`);
    });

    test('with no pending item at all, isGuest flipping to false calls neither onResume nor clearSessionJSONItem', () => {
      const onResume = vi.fn();
      const { rerender } = renderHook(
        ({ isGuest }) => usePendingWishlistItem({ productId: PRODUCT_ID, isGuest, onResume }),
        {
          initialProps: { isGuest: true },
        },
      );

      rerender({ isGuest: false });

      expect(onResume).not.toHaveBeenCalled();
      expect(mockClearSessionJSONItem).not.toHaveBeenCalled();
    });
  });

  describe('resume from session storage (Apple/Google redirect — a fresh mount, no prior React state)', () => {
    test('a fresh mount with isGuest already false and a matching stored intent resumes immediately', () => {
      mockGetSessionJSONItem.mockReturnValue({ productId: PRODUCT_ID, timestamp: Date.now() });
      const onResume = vi.fn();

      renderHook(() => usePendingWishlistItem({ productId: PRODUCT_ID, isGuest: false, onResume }));

      expect(onResume).toHaveBeenCalledTimes(1);
      expect(mockClearSessionJSONItem).toHaveBeenCalledWith(`zimmPendingWishlistCartItem:${PRODUCT_ID}`);
    });

    test('a stored intent for a DIFFERENT product is left untouched — not resumed, not cleared', () => {
      mockGetSessionJSONItem.mockReturnValue({ productId: OTHER_PRODUCT_ID, timestamp: Date.now() });
      const onResume = vi.fn();

      renderHook(() => usePendingWishlistItem({ productId: PRODUCT_ID, isGuest: false, onResume }));

      expect(onResume).not.toHaveBeenCalled();
      expect(mockClearSessionJSONItem).not.toHaveBeenCalled();
    });
  });

  describe('a pending item older than 5 minutes (pass criterion 10)', () => {
    test('from session storage: not resumed, but both stores are still cleared', () => {
      mockGetSessionJSONItem.mockReturnValue({ productId: PRODUCT_ID, timestamp: Date.now() - TEN_MINUTES_MS });
      const onResume = vi.fn();

      renderHook(() => usePendingWishlistItem({ productId: PRODUCT_ID, isGuest: false, onResume }));

      expect(onResume).not.toHaveBeenCalled();
      expect(mockClearSessionJSONItem).toHaveBeenCalledWith(`zimmPendingWishlistCartItem:${PRODUCT_ID}`);
    });

    test('from React state: not resumed once isGuest flips false, but both stores are still cleared', () => {
      // Mutation check on the fixture itself: a fresh (non-stale) timestamp on the exact same
      // path DOES resume (proved by the "resume from React state" describe block above), so this
      // failing when the timestamp is swapped for a stale one is a real assertion, not vacuous.
      const onResume = vi.fn();
      const { result, rerender } = renderHook(
        ({ isGuest }) => usePendingWishlistItem({ productId: PRODUCT_ID, isGuest, onResume }),
        {
          initialProps: { isGuest: true },
        },
      );

      act(() => result.current.beginPendingMove());
      // Directly age the in-memory intent's clock reference by controlling Date.now() at the
      // moment the resume effect actually checks freshness, rather than re-implementing
      // beginPendingMove with a hand-set timestamp.
      const dateNowSpy = vi.spyOn(Date, 'now').mockReturnValue(Date.now() + TEN_MINUTES_MS);
      rerender({ isGuest: false });
      dateNowSpy.mockRestore();

      expect(onResume).not.toHaveBeenCalled();
      expect(mockClearSessionJSONItem).toHaveBeenCalledWith(`zimmPendingWishlistCartItem:${PRODUCT_ID}`);
    });
  });

  describe('cross-row isolation — two different products never share one storage slot (rework fix)', () => {
    // The rest of this file's tests use a single mockReturnValue()/toHaveBeenCalledWith() per
    // test, which cannot represent two DIFFERENT keys coexisting at once — exactly the shape of
    // the defect being proven fixed here (row B's write silently clobbering row A's in the one
    // shared slot the hook used to read/write/clear unconditionally). This block backs the same
    // three mocked functions with a small real in-memory key/value store instead, scoped to these
    // tests only via its own beforeEach/afterEach — the outer beforeEach's
    // `mockGetSessionJSONItem.mockReturnValue(undefined)` runs first (outer beforeEach hooks run
    // before inner ones) and is immediately superseded by the mockImplementation below.
    let fakeStore: Record<string, unknown>;

    beforeEach(() => {
      fakeStore = {};
      mockSetSessionJSONItem.mockImplementation((key: string, value: unknown) => {
        fakeStore[key] = value;
      });
      mockGetSessionJSONItem.mockImplementation((key: string) => fakeStore[key]);
      mockClearSessionJSONItem.mockImplementation((key: string) => {
        delete fakeStore[key];
      });
    });

    // Restore the file's plain default-return-value mocks so a custom mockImplementation from
    // this block can never leak into a later test — see this describe's own comment above.
    afterEach(() => {
      mockSetSessionJSONItem.mockReset();
      mockGetSessionJSONItem.mockReset().mockReturnValue(undefined);
      mockClearSessionJSONItem.mockReset();
    });

    test('two guest clicks on two different rows persist under two different keys — the second does not overwrite the first', () => {
      const onResumeA = vi.fn();
      const onResumeB = vi.fn();
      const rowA = renderHook(() =>
        usePendingWishlistItem({ productId: PRODUCT_ID, isGuest: true, onResume: onResumeA }),
      );
      const rowB = renderHook(() =>
        usePendingWishlistItem({ productId: OTHER_PRODUCT_ID, isGuest: true, onResume: onResumeB }),
      );

      act(() => rowA.result.current.beginPendingMove());
      act(() => rowB.result.current.beginPendingMove());

      expect(Object.keys(fakeStore)).toHaveLength(2);
      expect(fakeStore[`zimmPendingWishlistCartItem:${PRODUCT_ID}`]).toMatchObject({ productId: PRODUCT_ID });
      expect(fakeStore[`zimmPendingWishlistCartItem:${OTHER_PRODUCT_ID}`]).toMatchObject({
        productId: OTHER_PRODUCT_ID,
      });
    });

    test('after a simulated page reload (fresh mounts, no prior React state for either row), both resume independently', () => {
      const onResumeA = vi.fn();
      const onResumeB = vi.fn();

      // Guest phase: row A begins a pending move, then (still guest, before any redirect
      // completes) row B does too — the Tester's exact reported sequence.
      const rowA = renderHook(() =>
        usePendingWishlistItem({ productId: PRODUCT_ID, isGuest: true, onResume: onResumeA }),
      );
      act(() => rowA.result.current.beginPendingMove());
      const rowB = renderHook(() =>
        usePendingWishlistItem({ productId: OTHER_PRODUCT_ID, isGuest: true, onResume: onResumeB }),
      );
      act(() => rowB.result.current.beginPendingMove());

      // The redirect reloads the page — both mounted instances (and all React state) are gone.
      rowA.unmount();
      rowB.unmount();

      // Post-redirect: fresh mounts, isGuest already false, nothing left but session storage —
      // mirrors the file's own "resume from session storage" describe block above, run for both
      // rows against the SAME underlying fake store.
      renderHook(() => usePendingWishlistItem({ productId: PRODUCT_ID, isGuest: false, onResume: onResumeA }));
      renderHook(() => usePendingWishlistItem({ productId: OTHER_PRODUCT_ID, isGuest: false, onResume: onResumeB }));

      expect(onResumeA).toHaveBeenCalledTimes(1);
      expect(onResumeB).toHaveBeenCalledTimes(1);
      // Each row cleared only its own key — nothing left over in either slot.
      expect(fakeStore).toEqual({});
    });

    test('the 5-minute staleness bound is judged per-product, independently — a stale row-A intent does not resume while a fresh row-B intent does, in the same store', () => {
      const onResumeA = vi.fn();
      const onResumeB = vi.fn();
      fakeStore[`zimmPendingWishlistCartItem:${PRODUCT_ID}`] = {
        productId: PRODUCT_ID,
        timestamp: Date.now() - TEN_MINUTES_MS,
      };
      fakeStore[`zimmPendingWishlistCartItem:${OTHER_PRODUCT_ID}`] = {
        productId: OTHER_PRODUCT_ID,
        timestamp: Date.now(),
      };

      renderHook(() => usePendingWishlistItem({ productId: PRODUCT_ID, isGuest: false, onResume: onResumeA }));
      renderHook(() => usePendingWishlistItem({ productId: OTHER_PRODUCT_ID, isGuest: false, onResume: onResumeB }));

      expect(onResumeA).not.toHaveBeenCalled();
      expect(onResumeB).toHaveBeenCalledTimes(1);
      // Both cleared regardless of freshness (matches the existing single-product staleness
      // cases above), now proved not to interfere with each other's independent clearing either.
      expect(fakeStore).toEqual({});
    });
  });
});

import { useEffect, useState } from 'react';
import {
  clearSessionJSONItem,
  getSessionJSONItem,
  setSessionJSONItem,
} from '@salesforce/retail-react-app/app/utils/utils';

/**
 * Outcome of one wishlist-move attempt. The actual SFCC SDK calls (wishlist add + cart removal)
 * are the caller's own responsibility — SFCC-11 plan step 4.6 (`cartDrawerContainer.tsx`, not
 * built yet) — this file only reports what happened, matching the exact discriminated-union
 * pattern `useCartMergeAndCap.ts`'s own `CartCapResult` already established
 * (`overrides/app/hooks/useCartMergeAndCap.ts:25-29`), per typescript.md's stated preference for
 * a discriminated union over a pile of optional fields.
 */
export type WishlistMoveResult =
  | { status: 'success' }
  | { status: 'already-in-wishlist' }
  | { status: 'error'; error: unknown };

/**
 * sessionStorage key PREFIX for "a guest asked to move THIS specific cart line to their wishlist
 * before authenticating." Namespaced per `productId` — see `pendingWishlistCartItemKey` below —
 * so that two different cart rows' pending intents can never collide in a single shared slot: a
 * guest beginning a pending move on row A, then row B, before either completes a redirect-based
 * auth flow, must leave both independently resumable rather than row B's write silently
 * overwriting row A's. Deliberately a distinct mechanism, and a distinct key, from
 * `useWishlistAuthDrawer.ts`'s own `PENDING_WISHLIST_INTENT_KEY`
 * (`overrides/app/hooks/useWishlistAuthDrawer.ts:43`): that key answers "which mounted drawer
 * instance's `onAuthSuccess` should fire after a social-IDP redirect" — its own
 * `PendingWishlistIntent` type carries only `intentId`/`timestamp`, no item identity at all.
 * This hook answers a different question — "which cart LINE was pending" — so it is a new,
 * separate mechanism rather than an addition to that shared type. The SFCC-11 plan explicitly
 * rejects adding an `itemId` field to that shared type: it has three other existing call sites
 * (header/rightBar, drawer-menu, product-view) and changing it is out of this step's scope.
 */
const PENDING_WISHLIST_CART_ITEM_KEY_PREFIX = 'zimmPendingWishlistCartItem';

/**
 * Builds the per-product sessionStorage key — see `PENDING_WISHLIST_CART_ITEM_KEY_PREFIX`'s own
 * doc for why storage is namespaced this way instead of one shared key.
 */
const pendingWishlistCartItemKey = (productId: string): string =>
  `${PENDING_WISHLIST_CART_ITEM_KEY_PREFIX}:${productId}`;

/**
 * Same 5-minute bound as `useWishlistAuthDrawer.ts`'s own `PENDING_WISHLIST_INTENT_MAX_AGE_MS`
 * (`overrides/app/hooks/useWishlistAuthDrawer.ts:52` — `5 * 60 * 1000`), and the same reasoning:
 * long enough for a real auth round trip, short enough that a long-abandoned attempt cannot
 * misfire later against a much later, unrelated cart session. Not imported from that file — the
 * constant is not exported there, and this step does not modify that file (out of scope; see the
 * SFCC-11 plan step 4.4's manifest and its "explicitly rejected" list). Redefined here as an
 * independent, same-valued constant instead.
 */
const PENDING_WISHLIST_MAX_AGE_MS = 5 * 60 * 1000; // 5 minutes

type PendingWishlistCartItem = {
  /**
   * Matched against this row's own `productId`, not `itemId` — deliberate. A guest's basket may
   * be merged into a registered customer's basket between the guest's click and the shopper
   * completing auth (SFCC-250 step 4.1, `useWishlistAuthDrawer.ts`'s own `isRegistered` effect),
   * and that merge can change which `itemId` a given product line carries (it merges into a
   * destination basket via `createDestinationBasket: true`). `productId` is stable across that
   * boundary; `itemId` is not — keying the match on `itemId` would risk silently failing to
   * resume a legitimate pending move the moment a merge has actually happened. See this step's
   * own report for the related, still-open sequencing question this raises for step 4.6.
   */
  productId: string;
  timestamp: number;
};

export type UsePendingWishlistItemParams = {
  /** Identifies this cart line for matching a resumed intent — see PendingWishlistCartItem's own
   *  doc comment for why this is `productId`, not `itemId`. */
  productId: string;
  /** Whether the current shopper is unauthenticated. Passed down from the caller (e.g. read once
   *  from `useCustomerType()` at the cart container) rather than read by this hook itself — see
   *  `zimmCartItemActions/index.tsx`'s own architecture note for why. */
  isGuest: boolean;
  /** Called (no arguments) once a previously-pending move for THIS row should be attempted.
   *  Fires at most once per stored intent — never for another row's pending item, never twice
   *  for the same one. */
  onResume: () => void | Promise<void>;
};

export type UsePendingWishlistItemReturn = {
  /** Call when a guest clicks "Move to Wishlist" for this row — persists the pending intent to
   *  both React state (survives the email-code/create-account flows, which never unload the
   *  page) and session storage (survives the Apple/Google redirect, which reloads it), so
   *  `onResume` fires automatically once `isGuest` becomes false for this same product. */
  beginPendingMove: () => void;
};

/**
 * Hook — persists a guest's "move to wishlist" intent for one cart line across an authentication
 * step, and resumes it once the shopper is no longer a guest. Extracted per
 * `.claude/rules/components.md`'s extract-to-hook threshold: this is React state plus a
 * non-trivial effect (session-storage read/write/clear, a 5-minute age check, resuming after a
 * simulated page reload) that would otherwise sit inline in `ZimmCartItemActions`.
 *
 * Deliberately calls no auth or `commerce-sdk-react` hook itself — `isGuest` arrives as a plain
 * prop, and the actual move (`onResume`) is the caller's own already-composed function. Only ONE
 * `useWishlistAuthDrawer` instance may exist for the whole cart (SFCC-11 plan step 4.4's own
 * explicit rejection of "one per line item"), so that real hook cannot live inside a component
 * that mounts once per cart line — this hook stays calling-hook-free so it can safely mount once
 * per row, alongside it, without reproducing that rejected shape.
 *
 * @returns `beginPendingMove`, the one function a guest click calls.
 */
export const usePendingWishlistItem = ({
  productId,
  isGuest,
  onResume,
}: UsePendingWishlistItemParams): UsePendingWishlistItemReturn => {
  const [pending, setPending] = useState<PendingWishlistCartItem | undefined>(undefined);

  const beginPendingMove = () => {
    const intent: PendingWishlistCartItem = { productId, timestamp: Date.now() };
    setPending(intent);
    setSessionJSONItem(pendingWishlistCartItemKey(productId), intent);
  };

  // Mirrors useWishlistAuthDrawer.ts's own redirect-consuming effect (that file's second
  // useEffect, [isRegistered]-only deps, overrides/app/hooks/useWishlistAuthDrawer.ts:252-259) —
  // runs on mount and on every `isGuest` change, not only on a true-to-false transition, because
  // a fresh mount after a real page reload (Apple/Google redirect) already has `isGuest === false`
  // on its very first render, with no transition to observe.
  useEffect(() => {
    if (isGuest) return;

    const stored = getSessionJSONItem(pendingWishlistCartItemKey(productId)) as PendingWishlistCartItem | undefined;
    // The per-product key above already means `stored` can only ever be what THIS row itself
    // wrote — a different row's pending intent lives under its own, different key and is never
    // read, resumed, or cleared from here. This productId match is a defensive belt-and-suspenders
    // check on top of that (never act on foreign/malformed data even if it somehow ended up in
    // this slot), not the mechanism that keeps two rows apart.
    const mineFromStorage = stored?.productId === productId ? stored : undefined;
    const candidate = pending ?? mineFromStorage;
    if (!candidate) return;

    // Found something of mine — clear both stores now, regardless of whether it turns out to be
    // fresh or stale below (a stale intent must not linger either — nothing resumes it later).
    // Only ever clears THIS row's own key — another row's still-pending intent, under its own
    // key, is untouched.
    setPending(undefined);
    clearSessionJSONItem(pendingWishlistCartItemKey(productId));

    const isFresh = Date.now() - candidate.timestamp <= PENDING_WISHLIST_MAX_AGE_MS;
    if (isFresh) {
      void onResume();
    }
  }, [isGuest]);

  return { beginPendingMove };
};

import type { ShopperBasketsTypes, ShopperProductsTypes } from 'commerce-sdk-isomorphic';
import { findImageGroupBy } from '@salesforce/retail-react-app/app/utils/image-groups-utils';
import { getDisplayVariationValues } from '@salesforce/retail-react-app/app/utils/product-utils';

/*
 * Converts an SDK basket `productItem` into a self-contained display-data shape, mirroring the
 * `productListCardMapper.ts` precedent (`overrides/app/pages/product-list/productListCardMapper.ts`,
 * PR #85) for how a page-scoped SDK-to-props mapper is organised in this codebase: exported
 * "select"-prefixed functions (that file exports three: `selectGalleryImages`,
 * `selectSizeChipValues`, `selectProductListCard` - corrected here, an earlier draft of this
 * comment said "a single" one, which was wrong), an untyped-base-package input narrowed to a
 * local type, and a `.test.ts` asserting the mapped shape directly (see that file's own
 * `ProductListSearchHit`/`RawImage` pattern, mirrored below for `CartLineItem`/`CartItemImage`).
 *
 * Disclosed design choice, not a directly sourced requirement (flagged per this step's own
 * instructions): `ProductItem`/`ItemVariantProvider` (`overrides/app/components/product-item/
 * index.tsx:140`, `overrides/app/components/item-variant/index.tsx:43`) both currently declare
 * their real data-carrying prop as the raw untyped basket/product object itself
 * (`product`/`variant`, both `SfccProduct`/`SfccVariant = any`) — today's leaves read every
 * display field (image, name, combined attributes) directly off that object via
 * `useItemVariant()`, not from individually-mapped props. This mapper is, per this step's plan
 * text, "an as-yet-unused-by-anything-else container-layer function" — it does not change or
 * feed either of those two files (out of this step's scope). What it produces instead is a pure,
 * tested equivalent of the specific per-field computations those leaves and
 * `product-quantity-picker.tsx`/`use-derived-product.js` already perform internally off that same
 * raw object (image+alt, combined colour/size, quantity, stepQuantity) — ready for whichever
 * future step decides how a real page hands data down, without having modified any of those
 * existing files.
 *
 * `CartLineItem` models the REAL runtime shape a basket line item has by the time it reaches
 * those leaves: the un-overridden base cart page never passes the raw `basket.productItems[i]`
 * alone — it merges it with the matching full `Product` (fetched separately via `useProducts`)
 * before handing it down: `product={{...productItem, ...productsByItemId[productItem.itemId],
 * price: productItem.price, quantity: ...}}` (see
 * `node_modules/@salesforce/retail-react-app/app/components/product-item-list/index.jsx`, the
 * `<ProductItem product={...}>` call). `imageGroups`/`variationAttributes`/`variationValues`/
 * `stepQuantity`/`name` all come from that merged-in `Product` half, not from
 * `ShopperBasketsTypes.ProductItem` itself (confirmed against its generated fields — it has no
 * image/variation/stepQuantity fields at all beyond its own `{[key: string]: any}` catch-all).
 *
 * Both halves are `Pick`'d, not intersected raw (zm-tester, SFCC-11 step 3.4 finding): the real
 * generated `ProductItem` type carries the identical `{[key: string]: any}` catch-all the comment
 * above already calls out on `Product`. Intersecting it raw would silently resolve a typo'd field
 * name (or a nonexistent one) to `any` instead of a compile error — empirically confirmed harmless
 * today (every real access below is spelled correctly) but a real, latent gap a future edit could
 * hit silently. `Pick`ing both halves closes it the same way on both sides.
 */
type CartLineItem = Pick<ShopperBasketsTypes.ProductItem, 'itemId' | 'productId' | 'quantity' | 'productName'> &
  Pick<
    ShopperProductsTypes.Product,
    'imageGroups' | 'variationAttributes' | 'variationValues' | 'stepQuantity' | 'name'
  >;

type CartItemImage = {
  src?: string;
  /**
   * Always a string, never undefined — even when there's no image at all (falls back to the
   * item's own name, then `''`). See `selectCartItemImage`'s own doc comment for the fallback
   * chain and why this differs from `productListCardMapper.ts`'s `toCardImage`, which returns
   * `undefined` for the whole image on a miss instead.
   */
  alt: string;
};

type CartItemMapperResult = {
  itemId?: string;
  productId?: string;
  name: string;
  image: CartItemImage;
  combinedAttributes: string;
  quantity?: number;
  stepQuantity: number;
};

/**
 * Matches `node_modules/@salesforce/retail-react-app/app/hooks/use-derived-product.js:38`'s own
 * `product?.stepQuantity || 1` exactly — reused as a value, not a shared import, since that hook
 * itself isn't a pure function this module can call (it's stateful, `useState`-backed).
 */
const DEFAULT_STEP_QUANTITY = 1;

/**
 * Selects this line item's display image, always returning a defined `alt` even when there is no
 * image at all (unlike `productListCardMapper.ts`'s `toCardImage`, which returns `undefined` for
 * the whole image on a miss — a PLP card can legitimately skip rendering entirely when it has
 * nothing to show; a cart line item cannot, per this step's own pass criteria).
 *
 * The lookup itself reuses `findImageGroupBy` exactly as
 * `overrides/app/components/item-variant/item-image.tsx:70-73` already does (same `viewType:
 * 'small'` / `selectedVariationAttributes` call) rather than reimplementing image-group matching.
 */
const selectCartItemImage = (item: CartLineItem): CartItemImage => {
  const image = findImageGroupBy(item.imageGroups, {
    viewType: 'small',
    selectedVariationAttributes: item.variationValues,
  })?.images?.[0];

  return {
    src: image?.disBaseLink || image?.link,
    alt: image?.alt || item.productName || item.name || '',
  };
};

/**
 * Combines the colour and size variation values into the single string the Figma cart-item spec
 * calls for, reusing the exact mechanism
 * `overrides/app/components/item-variant/item-attributes.tsx:98,148-150` already uses for its own
 * `combineAttributeValues` behaviour (`getDisplayVariationValues(...)` then
 * `Object.values(...).join(', ')`) rather than reimplementing string-combining from scratch.
 *
 * Ordering is inherited from that same call, not independently re-sorted here: it reflects
 * whichever order the incoming `variationValues` object's own keys are in (see
 * `getDisplayVariationValues`'s `Object.entries(values).reduce(...)`,
 * `node_modules/@salesforce/retail-react-app/app/utils/product-utils.js:30`). This is the
 * identical mechanism `item-attributes.tsx`'s own docblock (line 31) already cites as producing
 * "Lilac Sand, One size" (colour, size) for real Zimmermann catalog data —
 * `product-item/index.tsx`'s docblock (line 44) corroborates the same combined-string behaviour
 * generically ("colour, size") without repeating that specific example. This function inherits
 * that already-verified behaviour rather than re-guaranteeing the order independently.
 */
const selectCombinedAttributes = (item: CartLineItem): string => {
  const variationValues = getDisplayVariationValues(item.variationAttributes, item.variationValues);
  return variationValues ? Object.values(variationValues).join(', ') : '';
};

/**
 * Maps one basket line item (already merged with its full product data — see this file's own
 * module docblock) to a plain display-data shape: image, name, one combined colour/size string,
 * and quantity/stepQuantity passed through. Pure function, no hooks — keeps every consumer in B3
 * prop-driven with no data-fetching hook in a leaf, per this step's own plan text.
 */
export const selectCartItemProps = (item: CartLineItem): CartItemMapperResult => ({
  itemId: item.itemId,
  productId: item.productId,
  name: item.productName || item.name || '',
  image: selectCartItemImage(item),
  combinedAttributes: selectCombinedAttributes(item),
  quantity: item.quantity,
  stepQuantity: item.stepQuantity || DEFAULT_STEP_QUANTITY,
});
